using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using Codice.Expedition;using Codice.Characters;using Codice.Mechanics;using Codice.UI;using UnityEngine.AI;
public static class VerifyLiving {
 public static string Build(){string path="Assets/Resources/WorldProgression/IrelController.controller";var c=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(!c){c=AnimatorController.CreateAnimatorControllerAtPath(path);c.AddParameter("Moving",AnimatorControllerParameterType.Bool);AnimationClip Clip(string p)=>AssetDatabase.LoadAllAssetsAtPath(p).OfType<AnimationClip>().First(x=>!x.name.StartsWith("__"));var sm=c.layers[0].stateMachine;var idle=sm.AddState("Reposo");idle.motion=Clip("Assets/Kevin Iglesias/Human Animations/Animations/Male/Idles/HumanM@Idle01.fbx");var run=sm.AddState("Correr");run.motion=Clip("Assets/Kevin Iglesias/Human Animations/Animations/Male/Movement/Run/HumanM@Run01_Forward.fbx");run.speed=1.4f;sm.defaultState=idle;var a=idle.AddTransition(run);a.hasExitTime=false;a.duration=.15f;a.AddCondition(AnimatorConditionMode.If,0,"Moving");var b=run.AddTransition(idle);b.hasExitTime=false;b.duration=.15f;b.AddCondition(AnimatorConditionMode.IfNot,0,"Moving");AssetDatabase.SaveAssets();}return "Irel locomotion controller ready";}
 public static string Layouts(){int total=0,annex=0;for(int f=1;f<=12;f++)for(int keys=0;keys<8;keys++)for(int seed=1;seed<=60;seed++){var l=new ExpeditionLayout(seed,f,keys);if(!l.Connected()||l.Count>16)throw new Exception($"Map {seed}/{f}/{keys}");foreach(int r in Enumerable.Range(0,l.Count)){if(l.RoomAt(new Vector3(l.Rooms[r].x*4,l.Height(r),l.Rooms[r].y*4))!=r)throw new Exception("Overlapping centres");}if(keys>0&&f<7&&l.SideRooms.Count>0)annex++;total++;}return $"PASS {total} maps; {annex} early maps with unlocked annexes";}
 public static string Load(){PlayerPrefs.SetInt("Cinders.Tests.PreviousMemory",DescentMemory.Keys);PlayerPrefs.SetInt(DescentMemory.SaveKey,7);MainMenuUI.UnlockCheats("jam");ExpeditionFloor.DebugSeed=8137;RunNavigation.StartExpeditionTest(PlayerClass.Warrior,2);return "Loading 1-2, known keys";}
 public static string Contracts(){var r=RunDirector.Instance;var p=r.Player;p.State.LaboratoryImmortal=true;var f=r.Expedition;int gold=p.State.Gold;p.State.SpendGold(gold);var e=DescentEncounter.Create(p.transform.position,f.transform,DescentOffer.Pilgrim);e.Interact(p);if(e.Used||r.HiredPilgrim)throw new Exception("Free hire");p.State.AddGold(500);e.Interact(p);if(!e.Used||!r.HiredPilgrim||p.State.Gold!=320)throw new Exception("Hire payment");var d=DescentEncounter.Create(p.transform.position,f.transform,DescentOffer.Pilgrim);d.Interact(p);if(p.State.Gold!=320||d.Used)throw new Exception("Duplicate hire charged");var w=DescentEncounter.Create(p.transform.position,f.transform,DescentOffer.Wisp);w.Interact(p);if(!r.BondedWisp||p.State.Gold!=220)throw new Exception("Pet charge");if(UnityEngine.Object.FindObjectsByType<DescentCompanion>(FindObjectsSortMode.None).Length!=2)throw new Exception("Companion count");return "PASS cost, insufficient funds, duplicate refusal, 2 companions";}
 public static string Gate(){var f=RunDirector.Instance.Expedition;var p=RunDirector.Instance.Player;var wall=UnityEngine.Object.FindAnyObjectByType<SecretWall>();if(!wall)throw new Exception("No secret");wall.key=0;PlayerPrefs.SetInt(DescentMemory.SaveKey,0);var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=wall.transform.position+Vector3.left*2;cc.enabled=true;wall.Interact(p);if(f.SecretRevealed)throw new Exception("Gate opened without key");DescentMemory.Learn(0);wall.Interact(p);if(!f.SecretRevealed)throw new Exception("Key failed");PlayerPrefs.SetInt(DescentMemory.SaveKey,7);return "PASS required key, permanent unlock, gate opens";}
 public static string Restore(){PlayerPrefs.SetInt(DescentMemory.SaveKey,PlayerPrefs.GetInt("Cinders.Tests.PreviousMemory",0));PlayerPrefs.DeleteKey("Cinders.Tests.PreviousMemory");PlayerPrefs.Save();return "Original progression restored";}
 public static string CompanionState(){var r=RunDirector.Instance;return string.Join("; ",UnityEngine.Object.FindObjectsByType<DescentCompanion>(FindObjectsSortMode.None).Select(c=>c.name+" distance="+Vector3.Distance(c.transform.position,r.Player.transform.position)+" agent="+(c.Wisp?"wisp":c.GetComponent<NavMeshAgent>().isOnNavMesh.ToString())));}
}

